import { useState, useEffect, useMemo, useRef } from "react";
import { MapContainer, TileLayer, Popup, GeoJSON, useMap, Tooltip, FeatureGroup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

// --- Điều khiển Camera Map ---
function MapController({ zones, selectedDistrict, districts, viewAll }) {
  const map = useMap();
  useEffect(() => {
    if (selectedDistrict) {
      const dist = districts.find(d => d.id === selectedDistrict);
      if (dist && dist.center_lat) map.flyTo([dist.center_lat, dist.center_lng], 14);
    } else if (viewAll && zones.length > 0) {
      const bounds = zones.map(z => [z.center_lat, z.center_lng]);
      map.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [selectedDistrict, viewAll, zones, districts, map]);
  return null;
}

const API_BASE = "http://localhost:8000";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard"); // dashboard, sales, territories, assign
  const [districts, setDistricts] = useState([]);
  const [allZones, setAllZones] = useState([]);
  const [territories, setTerritories] = useState([]);
  const [statistics, setStatistics] = useState({});
  
  // Quản lý Phân vùng State
  const [selectedDistrict, setSelectedDistrict] = useState(null);
  const [viewAllZones, setViewAllZones] = useState(false);
  const [editingZone, setEditingZone] = useState(null);
  const [showDistrictForm, setShowDistrictForm] = useState(false);
  const [showTerritoryForm, setShowTerritoryForm] = useState(false);
  const [newDistrict, setNewDistrict] = useState({ code: "", name: "", center_lat: 21.02, center_lng: 105.83 });
  const [newTerritory, setNewTerritory] = useState({ name: "", zone_ids: [] });
  const [mapMode, setMapMode] = useState("view"); // view, select (chọn zones cho phân vùng mới)
  const [selectedZoneIds, setSelectedZoneIds] = useState([]);

  // Quản lý Sales State
  const [allSales, setAllSales] = useState([]);
  const [pendingSales, setPendingSales] = useState([]);
  const [salesFilter, setSalesFilter] = useState("all"); // pending, all

  // Quản lý Giao việc State
  const [workAssignDate, setWorkAssignDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedTerritory, setSelectedTerritory] = useState(null);
  const [selectedSalesForAssign, setSelectedSalesForAssign] = useState([]);
  const [availableSalesForAssign, setAvailableSalesForAssign] = useState([]);
  const [assignmentResult, setAssignmentResult] = useState(null);
  const [selectedAlgorithm, setSelectedAlgorithm] = useState("grasp"); // local_search, tabu_search, grasp
  const [salesToAdjust, setSalesToAdjust] = useState({});

  useEffect(() => {
    fetchInitialData();
    fetchSalesData();
    fetchTerritories();
  }, []);

  const fetchInitialData = async () => {
    try {
      const [dRes, zRes, sRes] = await Promise.all([
        fetch(`${API_BASE}/districts`),
        fetch(`${API_BASE}/zones`),
        fetch(`${API_BASE}/admin/statistics`)
      ]);
      setDistricts(await dRes.json());
      setAllZones(await zRes.json());
      setStatistics(await sRes.json());
    } catch (error) {
      console.error("Error fetching initial data:", error);
    }
  };

  const fetchSalesData = async () => {
    try {
      const [pRes, aRes] = await Promise.all([
        fetch(`${API_BASE}/admin/pending-sales`),
        fetch(`${API_BASE}/admin/all-sales`)
      ]);
      setPendingSales(await pRes.json());
      setAllSales(await aRes.json());
    } catch (error) {
      console.error("Error fetching sales:", error);
    }
  };

  const fetchTerritories = async () => {
    try {
      const res = await fetch(`${API_BASE}/territories`);
      const data = await res.json();
      setTerritories(data);
    } catch (error) {
      console.error("Error fetching territories:", error);
    }
  };

  // Compute displayedZones based on selectedDistrict and viewAllZones
  const displayedZones = useMemo(() => {
    if (selectedDistrict) {
      return allZones.filter(z => z.district_id === selectedDistrict);
    } else if (viewAllZones) {
      return allZones;
    }
    return [];
  }, [selectedDistrict, viewAllZones, allZones]);

  const handleApproveSales = async (userId, approve) => {
    try {
      const response = await fetch(`${API_BASE}/admin/approve-sales/${userId}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: userId, is_approved: approve })
      });
      const result = await response.json();
      
      if (response.ok) {
        alert(result.msg);
        fetchSalesData();
        fetchInitialData();
      } else {
        alert("Lỗi: " + result.detail);
      }
    } catch (error) {
      alert("Lỗi khi xử lý duyệt sales: " + error);
    }
  };

  const handleAddDistrict = async () => {
    try {
      const response = await fetch(`${API_BASE}/districts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newDistrict),
      });
      
      if (response.ok) {
        alert("Thêm quận thành công");
        setShowDistrictForm(false);
        setNewDistrict({ code: "", name: "", center_lat: 21.02, center_lng: 105.83 });
        fetchInitialData();
      } else {
        alert("Lỗi khi thêm quận");
      }
    } catch (error) {
      alert("Lỗi: " + error);
    }
  };

  const handleAddTerritory = async () => {
    if (!newTerritory.name.trim() || selectedZoneIds.length === 0) {
      alert("Vui lòng nhập tên phân vùng và chọn ít nhất 1 khu vực");
      return;
    }

    try {
      const response = await fetch(`${API_BASE}/territories`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newTerritory.name,
          zone_ids: selectedZoneIds
        }),
      });
      
      if (response.ok) {
        alert("Tạo phân vùng thành công");
        setShowTerritoryForm(false);
        setNewTerritory({ name: "", zone_ids: [] });
        setSelectedZoneIds([]);
        setMapMode("view");
        fetchTerritories();
      } else {
        alert("Lỗi khi tạo phân vùng");
      }
    } catch (error) {
      alert("Lỗi: " + error);
    }
  };

  const handleDeleteZone = async (id) => {
    if (!window.confirm("Xóa Zone này?")) return;
    try {
      await fetch(`${API_BASE}/zones/${id}`, { method: "DELETE" });
      fetchInitialData();
    } catch (error) {
      alert("Lỗi khi xóa zone: " + error);
    }
  };

  const handleUpdateZone = async (e) => {
    e.preventDefault();
    try {
      await fetch(`${API_BASE}/zones/${editingZone.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editingZone),
      });
      setEditingZone(null);
      fetchInitialData();
    } catch (error) {
      alert("Lỗi khi cập nhật zone: " + error);
    }
  };

  const fetchAvailableSalesForAssign = async (date) => {
    try {
      const response = await fetch(`${API_BASE}/admin/available-sales?date=${date}`);
      const data = await response.json();
      setAvailableSalesForAssign(data);
    } catch (error) {
      console.error("Error fetching available sales:", error);
    }
  };

  const handleAssignWork = async () => {
    if (!selectedTerritory || selectedSalesForAssign.length === 0) {
      alert("Vui lòng chọn phân vùng và ít nhất 1 sales");
      return;
    }

    try {
      const response = await fetch(`${API_BASE}/admin/assign-work`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          territory_id: selectedTerritory,
          sales_ids: selectedSalesForAssign,
          date: workAssignDate,
          algorithm: selectedAlgorithm
        })
      });

      const data = await response.json();
      if (response.ok) {
        setAssignmentResult(data);
        setSalesToAdjust(data.assignment);
      } else {
        alert("Lỗi: " + data.detail);
      }
    } catch (error) {
      alert("Lỗi khi giao việc: " + error);
    }
  };

  const handleSaveAdjustment = async () => {
    try {
      const response = await fetch(`${API_BASE}/admin/save-assignment`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(salesToAdjust)
      });

      if (response.ok) {
        alert("Lưu phân công thành công");
        setAssignmentResult(null);
        setSalesToAdjust({});
      } else {
        alert("Lỗi khi lưu phân công");
      }
    } catch (error) {
      alert("Lỗi: " + error);
    }
  };

  const getZoneColor = (id) => `hsl(${(id * 137.5) % 360}, 70%, 50%)`;

  return (
    <div className="admin-container">
      {/* SIDEBAR CHÍNH */}
      <aside className="admin-sidebar">
        <div className="logo">🚀 Territory Admin</div>
        <nav className="main-nav">
          <button className={activeTab === "dashboard" ? "active" : ""} onClick={() => setActiveTab("dashboard")}>📊 Dashboard</button>
          <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>👥 Quản lý Sales</button>
          <button className={activeTab === "territories" ? "active" : ""} onClick={() => setActiveTab("territories")}>🗺️ Quản lý Phân vùng</button>
          <button className={activeTab === "assign" ? "active" : ""} onClick={() => setActiveTab("assign")}>✓ Giao việc</button>
        </nav>
        <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
      </aside>

      <main className="admin-main">
        {/* 1. TAB DASHBOARD */}
        {activeTab === "dashboard" && (
          <div className="tab-content">
            <h2>Tổng quan hệ thống</h2>
            <div className="stats-grid">
              <div className="stat-card"><h3>{statistics.total_zones}</h3><p>Tổng số Zones</p></div>
              <div className="stat-card"><h3>{statistics.total_sales}</h3><p>Nhân viên Sales</p></div>
              <div className="stat-card"><h3>{statistics.total_revenue?.toLocaleString()}</h3><p>Doanh thu (VND)</p></div>
              <div className="stat-card"><h3>{territories.length}</h3><p>Phân vùng</p></div>
            </div>
          </div>
        )}

        {/* 3. TAB QUẢN LÝ PHÂN VÙNG */}
        {activeTab === "territories" && (
          <div className="tab-content">
            <div className="zone-mgr-header">
              <h2>🗺️ Quản lý Phân vùng</h2>
              <div className="manager-buttons">
                <button className="btn-primary" onClick={() => setShowDistrictForm(true)}>➕ Thêm Quận</button>
                <button className="btn-primary" onClick={() => {
                  setShowTerritoryForm(true);
                  setMapMode("select");
                  setSelectedZoneIds([]);
                }}>
                  ➕ Thêm Phân vùng
                </button>
              </div>
            </div>

            <div className="zone-mgr-layout">
              {/* Danh sách Quận bên trái */}
              <div className="district-list">
                <h4>Danh sách Quận</h4>
                <button 
                  className={`dist-item ${viewAllZones ? "active" : ""}`}
                  onClick={() => { setViewAllZones(true); setSelectedDistrict(null); }}
                >
                  🌍 Xem toàn bộ Zones
                </button>
                <hr />
                {districts.map(d => (
                  <button 
                    key={d.id}
                    className={`dist-item ${selectedDistrict === d.id ? "active" : ""}`}
                    onClick={() => { setSelectedDistrict(d.id); setViewAllZones(false); }}
                  >
                    🏙️ {d.name}
                  </button>
                ))}
              </div>

              {/* Nội dung hiển thị bên phải */}
              <div className="zone-display">
                <div className="map-box">
                  <MapContainer center={[21.02, 105.83]} zoom={12} style={{ height: '400px', borderRadius: '8px' }}>
                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                    <MapController zones={displayedZones} selectedDistrict={selectedDistrict} districts={districts} viewAll={viewAllZones} />
                    {displayedZones.map(z => {
                      const isSelected = selectedZoneIds.includes(z.id);
                      return (
                        <div key={z.id}>
                          <GeoJSON 
                            data={z.geometry} 
                            style={{ 
                              color: isSelected ? '#FF0000' : getZoneColor(z.id), 
                              fillOpacity: isSelected ? 0.7 : 0.5,
                              weight: isSelected ? 3 : 2
                            }}
                            onEachFeature={(feature, layer) => {
                              if (mapMode === "select") {
                                layer.on('click', () => {
                                  if (isSelected) {
                                    setSelectedZoneIds(selectedZoneIds.filter(id => id !== z.id));
                                  } else {
                                    setSelectedZoneIds([...selectedZoneIds, z.id]);
                                  }
                                });
                                layer.setStyle({ cursor: 'pointer' });
                              }
                            }}
                          >
                            <Popup><strong>{z.name}</strong><br/>Mã: {z.zone_code}</Popup>
                          </GeoJSON>
                        </div>
                      );
                    })}
                  </MapContainer>
                  {mapMode === "select" && (
                    <div className="map-info">
                      💡 Click vào các zones trên bản đồ để chọn cho phân vùng mới ({selectedZoneIds.length} zone đã chọn)
                    </div>
                  )}
                </div>

                {selectedDistrict && displayedZones.length > 0 && (
                  <div className="zone-table-box">
                    <h3>Danh sách phường/xã thuộc Quận</h3>
                    <table className="admin-table">
                      <thead>
                        <tr>
                          <th>Mã</th>
                          <th>Tên</th>
                          <th>Khách hàng</th>
                          <th>Đơn hàng</th>
                          <th>Doanh thu</th>
                          <th>Thao tác</th>
                        </tr>
                      </thead>
                      <tbody>
                        {displayedZones.map(z => (
                          <tr key={z.id}>
                            <td>{z.zone_code}</td>
                            <td>{z.name}</td>
                            <td>{z.num_customers}</td>
                            <td>{z.num_orders}</td>
                            <td>{z.revenue.toLocaleString()}</td>
                            <td>
                              <button className="btn-sm-edit" onClick={() => setEditingZone(z)}>✏️</button>
                              <button className="btn-sm-delete" onClick={() => handleDeleteZone(z.id)}>🗑️</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}

                {territories.length > 0 && (
                  <div className="territories-box">
                    <h3>Danh sách Phân vùng hiện tại</h3>
                    <div className="territories-list">
                      {territories.map(t => (
                        <div key={t.id} className="territory-item">
                          <strong>{t.name}</strong>
                          <p>📍 {t.zone_ids?.length || 0} zones</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {/* 4. TAB GIAO VIỆC */}
        {activeTab === "assign" && (
          <div className="tab-content">
            <h2>✓ Giao việc cho Sales</h2>
            
            {!assignmentResult ? (
              <div className="assign-form-section">
                <div className="form-group">
                  <label>Chọn ngày giao việc:</label>
                  <input 
                    type="date" 
                    value={workAssignDate}
                    onChange={(e) => {
                      setWorkAssignDate(e.target.value);
                      fetchAvailableSalesForAssign(e.target.value);
                    }}
                  />
                </div>

                <div className="form-group">
                  <label>Chọn Phân vùng:</label>
                  <select value={selectedTerritory || ""} onChange={(e) => setSelectedTerritory(Number(e.target.value))}>
                    <option value="">-- Chọn phân vùng --</option>
                    {territories.map(t => (
                      <option key={t.id} value={t.id}>{t.name}</option>
                    ))}
                  </select>
                </div>

                <div className="form-group">
                  <label>Chọn thuật toán:</label>
                  <div className="algorithm-options">
                    <label>
                      <input 
                        type="radio" 
                        value="local_search"
                        checked={selectedAlgorithm === "local_search"}
                        onChange={(e) => setSelectedAlgorithm(e.target.value)}
                      />
                      Local Search
                    </label>
                    <label>
                      <input 
                        type="radio" 
                        value="tabu_search"
                        checked={selectedAlgorithm === "tabu_search"}
                        onChange={(e) => setSelectedAlgorithm(e.target.value)}
                      />
                      Tabu Search
                    </label>
                    <label>
                      <input 
                        type="radio" 
                        value="grasp"
                        checked={selectedAlgorithm === "grasp"}
                        onChange={(e) => setSelectedAlgorithm(e.target.value)}
                      />
                      Reactive GRASP (Khuyến nghị)
                    </label>
                  </div>
                </div>

                <div className="form-group">
                  <label>Danh sách Sales chưa được phân công ({availableSalesForAssign.length}):</label>
                  <div className="sales-selection">
                    {availableSalesForAssign.length === 0 ? (
                      <p className="empty-msg">Không có sales nào chờ phân công vào ngày này</p>
                    ) : (
                      availableSalesForAssign.map(s => (
                        <label key={s.id} className="checkbox-item">
                          <input 
                            type="checkbox"
                            checked={selectedSalesForAssign.includes(s.id)}
                            onChange={(e) => {
                              if (e.target.checked) {
                                setSelectedSalesForAssign([...selectedSalesForAssign, s.id]);
                              } else {
                                setSelectedSalesForAssign(selectedSalesForAssign.filter(id => id !== s.id));
                              }
                            }}
                          />
                          <span>{s.full_name || s.username}</span>
                        </label>
                      ))
                    )}
                  </div>
                </div>

                <div className="form-actions">
                  <button 
                    className="btn-primary"
                    onClick={handleAssignWork}
                    disabled={!selectedTerritory || selectedSalesForAssign.length === 0}
                  >
                    🚀 Chạy thuật toán chia việc
                  </button>
                </div>
              </div>
            ) : (
              <div className="assignment-result-section">
                <div className="result-header">
                  <h3>📊 Kết quả chia việc</h3>
                  <p>Thuật toán: <strong>{selectedAlgorithm}</strong></p>
                </div>

                <div className="assignment-metrics">
                  <div className="metric-card">
                    <p>Hệ số biến thiên (CV)</p>
                    <h4>{assignmentResult.cv_pct?.toFixed(2)}%</h4>
                  </div>
                  <div className="metric-card">
                    <p>Tổng quãng đường</p>
                    <h4>{assignmentResult.total_distance?.toFixed(2)}</h4>
                  </div>
                  <div className="metric-card">
                    <p>Chỉ số Hoover</p>
                    <h4>{assignmentResult.hoover_index?.toFixed(2)}%</h4>
                  </div>
                </div>

                <div className="territories-adjustment">
                  <h4>Điều chỉnh phân công:</h4>
                  <p className="adjustment-info">💡 Bạn có thể kéo và thả để điều chỉnh lại phân công giữa các sales</p>
                  
                  <div className="adjustment-table">
                    <table>
                      <thead>
                        <tr>
                          <th>Sales</th>
                          <th>Zones được giao</th>
                          <th>Workload</th>
                        </tr>
                      </thead>
                      <tbody>
                        {Object.entries(salesToAdjust).map(([salesId, zones]) => {
                          const totalWorkload = zones.reduce((sum, zId) => {
                            const zone = allZones.find(z => z.id === zId);
                            return sum + (zone?.num_customers * 1.0 + zone?.num_orders * 0.2 || 0);
                          }, 0);
                          
                          return (
                            <tr key={salesId}>
                              <td>
                                {availableSalesForAssign.find(s => s.id === Number(salesId))?.full_name || 
                                 availableSalesForAssign.find(s => s.id === Number(salesId))?.username}
                              </td>
                              <td>
                                <div className="zone-list">
                                  {zones.map(zId => {
                                    const zone = allZones.find(z => z.id === zId);
                                    return (
                                      <span key={zId} className="zone-tag">
                                        {zone?.name}
                                      </span>
                                    );
                                  })}
                                </div>
                              </td>
                              <td>{totalWorkload?.toFixed(2)}</td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>

                <div className="result-actions">
                  <button 
                    className="btn-success"
                    onClick={handleSaveAdjustment}
                  >
                    ✓ Lưu phân công
                  </button>
                  <button 
                    className="btn-secondary"
                    onClick={() => {
                      setAssignmentResult(null);
                      setSalesToAdjust({});
                    }}
                  >
                    ◀ Quay lại
                  </button>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      {/* MODAL SỬA ZONE */}
      {editingZone && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Chỉnh sửa thông tin Zone</h3>
            <form onSubmit={handleUpdateZone}>
              <label>Số khách hàng:</label>
              <input type="number" value={editingZone.num_customers} onChange={e => setEditingZone({...editingZone, num_customers: e.target.value})} />
              <label>Số đơn hàng:</label>
              <input type="number" value={editingZone.num_orders} onChange={e => setEditingZone({...editingZone, num_orders: e.target.value})} />
              <label>Doanh thu:</label>
              <input type="number" value={editingZone.revenue} onChange={e => setEditingZone({...editingZone, revenue: e.target.value})} />
              <div className="modal-btns">
                <button type="submit" className="btn-success">Lưu</button>
                <button type="button" onClick={() => setEditingZone(null)}>Hủy</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL THÊM QUẬN */}
      {showDistrictForm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Thêm Quận/Huyện mới</h3>
            <input type="text" placeholder="Mã Quận (VD: CG)" value={newDistrict.code} onChange={e => setNewDistrict({...newDistrict, code: e.target.value})} />
            <input type="text" placeholder="Tên Quận (VD: Cầu Giấy)" value={newDistrict.name} onChange={e => setNewDistrict({...newDistrict, name: e.target.value})} />
            <div className="modal-btns">
              <button className="btn-success" onClick={handleAddDistrict}>Thêm</button>
              <button onClick={() => setShowDistrictForm(false)}>Hủy</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL THÊM PHÂN VÙNG */}
      {showTerritoryForm && (
        <div className="modal-overlay">
          <div className="modal-content modal-large">
            <h3>Tạo Phân vùng mới</h3>
            <input 
              type="text" 
              placeholder="Tên Phân vùng (VD: Phân vùng Bắc)" 
              value={newTerritory.name}
              onChange={e => setNewTerritory({...newTerritory, name: e.target.value})}
            />
            <p className="territory-help">
              ✓ Đã chọn {selectedZoneIds.length} zone(s)
            </p>
            <div className="modal-btns">
              <button className="btn-success" onClick={handleAddTerritory}>Tạo Phân vùng</button>
              <button onClick={() => {
                setShowTerritoryForm(false);
                setMapMode("view");
                setSelectedZoneIds([]);
              }}>Hủy</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
